import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Subflow, wfa } from '@servicenow/sdk/automation'

/**
 * Test subflow for AssignSubflowOutputs validation - invalid output type
 * Should fail: Output cannot use local variable references (IdentifierShape)
 */
export const assignSubflowOutputsInvalidType = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-invalid-type'],
        name: 'AssignSubflowOutputs Invalid Type Test',
        description: 'Test AssignSubflowOutputs validation with invalid output type',
        inputs: {
            inputData: StringColumn({
                label: 'Input Data',
                mandatory: true,
            }),
        },
        outputs: {
            result: StringColumn({
                label: 'Result',
                mandatory: true,
            }),
        },
    },
    (params) => {
        const localVariable = 'test value' // Local variable

        // This should fail validation: cannot use local variable (IdentifierShape)
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-invalid-type'],
                annotation: 'Invalid: local variable reference',
            },
            params.outputs,
            {
                result: localVariable as any, // Invalid: identifier/local variable
            }
        )
    }
)
